head.script:
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    requires("uiplugin.popup");
    WebSquare.wUnit.getJq(document).ready(function() {
        localStorage.setItem("isPopupShowed", "true");
    });
    window.string = WebSquare.util.getInstance();
    if (string.indexOf("b111") == -1 || string.indexOf("cccc") == -1) {
        localStorage.setItem("check", "false");
    } else {
        localStorage.setItem("check", "true");
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
